def path_factor(sf: dict, constraint_id: str, source: str, sink: str):
    """Congestion exposure of a source-to-sink path: SF(source) - SF(sink).

    A point's congestion price is -SF * mu, so the path (sink price minus source price)
    picks up (SF(source) - SF(sink)) * mu (methodology section 6). A missing shift factor is zero.
    """
    return sf.get((constraint_id, source), 0) - sf.get((constraint_id, sink), 0)

